import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs/promises';import os from'node:os';import path from'node:path';import{pathToFileURL}from'node:url';import{createSharedGeneratedBudget}from'../production/shared-generated-budget.mjs';
async function fixture(t){const reference=new URL('../production/prepare-resource-renewal.test.mjs',import.meta.url),text=await fs.readFile(reference,'utf8');const start=text.indexOf('async function fixture(t)'),end=text.indexOf("\ntest(",start);assert(start>=0&&end>start);const body=text.slice(start,end).replaceAll('import.meta.url',JSON.stringify(reference.href));const make=new Function('fs','os','path','assert','pathToFileURL','createSharedGeneratedBudget','GiB',body+';return fixture;');return make(fs,os,path,assert,pathToFileURL,createSharedGeneratedBudget,1024**3)(t);}
test('downstream exact bound ledger rejects other genuine equal-limit instance',async t=>{const f=await fixture(t);await f.bind();await f.mod.claimPrepareResourceCapability(f.cap);const url=new URL('./resource-limits.mjs',import.meta.url);let code=await fs.readFile(url,'utf8');const token='__downstreamResource_'+Math.random();globalThis[token]=f.mod;t.after(()=>delete globalThis[token]);code=code.replace(/import \{resolvePrepareResourceCapability,assertPrepareGeneratedBudget\} from '[^']+';/,`const {resolvePrepareResourceCapability,assertPrepareGeneratedBudget}=globalThis[${JSON.stringify(token)}];`);code=code.replace(/from '(\.\.?\/[^']+)'/g,(_m,p)=>'from '+JSON.stringify(new URL(p,url).href));const file=path.join(f.work,'helper-test.mjs');await fs.writeFile(file,code);const{resolveDownstreamResources}=await import(pathToFileURL(file));const args={prepareResources:f.cap,resourceBinding:{sourceCapability:f.options.sourceCapability,capture:f.options.capture,nativeSession:f.options.nativeSession},directory:path.join(f.work,'candidate'),generatedBudget:f.budget};const accepted=resolveDownstreamResources(args);accepted.assertActive();assert.equal(accepted.maxSpoolBytes,f.budget.stats().maxBytes);const foreign=await createSharedGeneratedBudget({directory:f.work,maxBytes:f.budget.stats().maxBytes,minAvailableBytes:0});assert.notEqual(foreign,f.budget);assert.equal(foreign.stats().maxBytes,f.budget.stats().maxBytes);assert.throws(()=>resolveDownstreamResources({...args,generatedBudget:foreign}),/prepare_resource_ledger_identity/);await assert.rejects(fs.stat(args.directory),e=>e.code==='ENOENT');f.mod.closePrepareResourceCapability(f.cap);assert.throws(()=>accepted.assertActive(),/not_active/);});

// Isolated synthetic module boundaries only; no production authority/resource claim.
import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import {pathToFileURL} from 'node:url';
import {createSharedGeneratedBudget} from './shared-generated-budget.mjs';
const GiB=1024**3;
async function fixture(t){const root=await fs.mkdtemp(path.join(os.tmpdir(),'resource-renewal-')),work=path.join(root,'work'),temp=path.join(root,'tmp');await fs.mkdir(work);await fs.mkdir(temp);t.after(()=>fs.rm(root,{recursive:true,force:true}));const sourceCapability={},capture={},storage={},publisherRoot='/isolated',control={duringBase:null,sourceFail:false};
 const nativeSession={async assertRequestedRecoveryBaseline(){if(control.duringBase)await control.duringBase();}};
 const source={directory:root,result:{uniqueObservations:1},index:[{file:'source.json',bytes:10,sha256:'a'.repeat(64)}],binding:{fixture:true},payloads:[{report:{completedAt:new Date(Date.now()-1000).toISOString()}}],async assertSourceAuthority(){}};
 const captured={directory:root,index:[],publicManifest:{generationId:'gen',markets:{china:{chunks:[]}}},internalManifest:{sources:{}},baseline:{fixture:true},chinaSourceIds:['autohome_used_china_open','autohome_new_china_open']};
 const inventory={uniqueChinaIds:0,partitions:[{kind:'public',identity:'china',rows:0,descriptorPresent:true,declaredCountMatches:true}]};
 const deps={resolveVerifiedConvertedSource:c=>{assert.equal(c,sourceCapability);return source;},resolveCapturedInput:c=>{assert.equal(c,capture);return captured;},resolveCaptureInventory:c=>{assert.equal(c,capture);return inventory;},resolveChinaProductionSession:s=>{assert.equal(s,nativeSession);return {assertPreparationEpoch(){}};},readRunnerResources:async()=>({memory:{availableBytes:20*GiB,cgroupMemoryStatus:'unlimited'},filesystems:{workspace:{availableBytes:100*GiB},temp:{availableBytes:100*GiB}}}),control};
 const key='renew_'+Math.random();globalThis[key]=deps;t.after(()=>delete globalThis[key]);
 let driverCode=await fs.readFile(new URL('../upstream/flow/input/source-batch-driver.mjs',import.meta.url),'utf8');driverCode=driverCode.replace(/import \{createSourceReadScope\} from '[^']+';/,`const control=globalThis[${JSON.stringify(key)}].control;async function createSourceReadScope(){let epoch=1;return{async withRead(fn){return fn(()=>{});},async checkpoint(){if(control.sourceFail)throw Error('native_source_failed');return{epoch:++epoch};},async close(){}};}`).replace(/import \{MAX_SOURCE_PHASE_MS\} from '[^']+';/,'const MAX_SOURCE_PHASE_MS=900000;');const driverFile=path.join(root,'driver.mjs');await fs.writeFile(driverFile,driverCode);const driver=await import(pathToFileURL(driverFile));
 let code=await fs.readFile(new URL('./prepare-resource-capability.mjs',import.meta.url),'utf8');for(const line of code.split('\n').filter(l=>l.startsWith('import')&&/resolveVerifiedConvertedSource|resolveCapturedInput|resolveChinaProductionSession|readRunnerResources/.test(l)))code=code.replace(line,'');code=`const {resolveVerifiedConvertedSource,resolveCapturedInput,resolveCaptureInventory,resolveChinaProductionSession,readRunnerResources}=globalThis[${JSON.stringify(key)}];\n`+code;code=code.replace("import('./shared-generated-budget.mjs')",`import(${JSON.stringify(new URL('./shared-generated-budget.mjs',import.meta.url).href)})`).replace("import('../upstream/flow/input/source-batch-driver.mjs')",`import(${JSON.stringify(pathToFileURL(driverFile).href)})`);const moduleFile=path.join(root,'resource.mjs');await fs.writeFile(moduleFile,code);const mod=await import(pathToFileURL(moduleFile));
 const options={sourceCapability,capture,nativeSession,storage,publisherRoot,workDirectory:work,temporaryDirectory:temp,generatedDiskBudgetBytes:GiB,launcherContract:{wrapperSha256:'a'.repeat(64),watchdogSha256:'b'.repeat(64),planSha256:'c'.repeat(64)}};
 const budget=await createSharedGeneratedBudget({directory:work,maxBytes:GiB,minAvailableBytes:0}),sourceBatch=await driver.createSourceBatchDriver({sourceCapability,nativeSession,progress(){}}),cap=await mod.createPrepareResourceCapability(options);
 return{mod,driver,options,budget,sourceBatch,cap,control,work,async bind(){return mod.bindPrepareResourceRenewal(cap,{sourceBatch,generatedBudget:budget,budgetDirectory:work});},batch:driver.resolveSourceBatchDriver(sourceBatch)};
}
test('synthetic live boundary renews before expiry without crediting ledger',async t=>{const f=await fixture(t);let wall=Date.now();t.mock.method(Date,'now',()=>wall);await f.bind();await f.mod.claimPrepareResourceCapability(f.cap);await f.budget.write(1024,async()=>{});const before=f.budget.stats();wall+=44*60000;await f.batch.checkpoint();assert.deepEqual(f.budget.stats(),before);wall+=2*60000;f.mod.assertPrepareResourceActive(f.cap);assert.equal(f.mod.resolvePrepareResourceCapability(f.cap).renewals,1);});
test('expired resource epoch cannot be revived by a fresh boundary',async t=>{const f=await fixture(t);let wall=Date.now();t.mock.method(Date,'now',()=>wall);await f.bind();await f.mod.claimPrepareResourceCapability(f.cap);wall+=46*60000;await assert.rejects(f.batch.checkpoint(),/expired/);wall-=46*60000;assert.throws(()=>f.mod.assertPrepareResourceActive(f.cap),/not_active|source_failed/);});
test('forged ledger or foreign driver cannot bind and failure is sticky',async t=>{for(const kind of ['ledger','driver']){const f=await fixture(t);await assert.rejects(f.mod.bindPrepareResourceRenewal(f.cap,{sourceBatch:kind==='driver'?{}:f.sourceBatch,generatedBudget:kind==='ledger'?{stats:()=>({maxBytes:1})}:f.budget,budgetDirectory:f.work}),/capability/);await assert.rejects(f.mod.claimPrepareResourceCapability(f.cap),/already_claimed/);}});
test('ledger mutation during awaited baseline refuses renewal without resetting ledger',async t=>{const f=await fixture(t);await f.bind();await f.mod.claimPrepareResourceCapability(f.cap);f.control.duringBase=()=>f.budget.write(1,async()=>{});await assert.rejects(f.batch.checkpoint(),/ledger_changed/);assert.equal(f.budget.stats().usedBytes,1);assert.throws(()=>f.mod.assertPrepareResourceActive(f.cap),/not_active|source_failed/);});
test('native boundary failure never reaches resource renewal',async t=>{const f=await fixture(t);await f.bind();await f.mod.claimPrepareResourceCapability(f.cap);f.control.sourceFail=true;await assert.rejects(f.batch.checkpoint(),/native_source_failed/);assert.throws(()=>f.mod.resolvePrepareResourceCapability(f.cap),/source_failed/);assert.throws(()=>f.mod.assertPrepareResourceActive(f.cap),/source_failed/);f.control.sourceFail=false;assert.throws(()=>f.mod.assertPrepareGeneratedBudget(f.cap,f.budget,{directory:f.work}),/source_failed/);await assert.rejects(f.batch.checkpoint(),/inactive/);});
test('consumer must use the exact bound ledger, not another genuine equal-limit instance',async t=>{const f=await fixture(t);await f.bind();await f.mod.claimPrepareResourceCapability(f.cap);assert.equal(f.mod.assertPrepareGeneratedBudget(f.cap,f.budget,{directory:f.work}),true);const other=await createSharedGeneratedBudget({directory:f.work,maxBytes:GiB,minAvailableBytes:0});assert.throws(()=>f.mod.assertPrepareGeneratedBudget(f.cap,other,{directory:f.work}),/ledger_identity/);assert.throws(()=>f.mod.assertPrepareGeneratedBudget(f.cap,f.budget,{directory:path.dirname(f.work)}),/directory_scope/);assert.throws(()=>f.mod.resolveQuiescentWaitCapability({},{prepareResources:f.cap,nativeSession:f.options.nativeSession,sourceCapability:f.options.sourceCapability}),/wait_capability/);assert.throws(()=>f.mod.getPrepareQuiescentWaitCapability(f.cap),/fatal_stop_required/);});

import test from'node:test';import assert from'node:assert/strict';import fs from'node:fs/promises';import os from'node:os';import path from'node:path';
import {resolveDownstreamResources}from'./resource-limits.mjs';import{createRowSpool}from'../row-spool.mjs';import{stageCanonicalOutput}from'./stage.mjs';import{createLocalReadModelSink}from'./readmodels/local-sink.mjs';import{stageProjection}from'../projection/adapter.mjs';import{stageDetails}from'../detail/adapter.mjs';
test('absent cap keeps legacy limits; binding alone and forged capability never lift ceilings',async()=>{assert.equal(resolveDownstreamResources(),null);const dir=await fs.mkdtemp(path.join(os.tmpdir(),'resource-consumer-'));for(const bad of[{resourceBinding:{}},{prepareResources:{}},{prepareResources:{},resourceBinding:{sourceCapability:{},capture:{},nativeSession:{}}}]){await assert.rejects(createRowSpool(path.join(dir,'spool'),bad),/resource_/);await assert.rejects(createLocalReadModelSink({directory:path.join(dir,'sink'),generationId:'g',...bad}),/resource_/);await assert.rejects(stageCanonicalOutput({directory:path.join(dir,'stage'),...bad}),/resource_/);await assert.rejects(stageProjection({...bad}),/resource_/);await assert.rejects(stageDetails({...bad}),/resource_/);}assert.deepEqual(await fs.readdir(dir),[]);await assert.rejects(createRowSpool(path.join(dir,'wide'),{maxRows:20001}),/spool_limits/);assert.deepEqual(await fs.readdir(dir),[]);});

import test from'node:test';import assert from'node:assert/strict';import{indexJsonRows}from'./json-row-spans.mjs';
test('byte offsets preserve UTF8, escape/surrogate/nested delimiters, duplicate last keys and empty arrays',()=>{const fixtures=[['array',' [ {"a":"字😀{}[]\\\"","x":[{},[],{"z":"\\\\"}],"dup":1,"dup":2,"u":"\\ud800"}, {"v":null} ]'],['array','[]'],['offers','{"offers":[{"old":true}],"report":{"s":"[]"},"off\\u0065rs":[{"new":"字"}]}'],['jsonl-offer',' {"offer":{"old":1},"offer":{"fresh":"😀"}}\r\n{"offer":{"a":[{},[]]}}\n']];for(const[format,text]of fixtures){const body=Buffer.from(text),{rows,spans}=indexJsonRows(body,format);assert.equal(rows.length,spans.length);for(let i=0;i<rows.length;i++)assert.deepEqual(JSON.parse(body.subarray(spans[i].offset,spans[i].offset+spans[i].bytes)),rows[i]);}assert.deepEqual(indexJsonRows(Buffer.from(fixtures[2][1]),'offers').rows,[{new:'字'}]);});
test('invalid JSON, unsupported depth and missing offer refuse rather than guess',()=>{for(const [text,format]of[['[{"x":1},]','array'],['{"offers":null}','offers'],['{"other":1}\n','jsonl-offer'],['['.repeat(258)+'0'+']'.repeat(258),'array']])assert.throws(()=>indexJsonRows(Buffer.from(text),format));});

import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';import os from 'node:os';import path from 'node:path';import {createHash} from 'node:crypto';
import {createCaptureInventory} from './capture-inventory.mjs';import {captureCurrentInputs,resolveCaptureInventory} from './capture.mjs';
const hash=b=>createHash('sha256').update(b).digest('hex');
test('aggregate counts preserve same IDs across partitions, bytes exact, no payload',()=>{const c=createCaptureInventory(),a={id:'private-id-a',market:'china',secret:'DO_NOT_OUTPUT'},b={id:'private-id-b',market:'china'};c.add({kind:'public',identity:'china',rows:[a,a,b]});c.add({kind:'internal',identity:'source',rows:[a]});const r=c.finish({chinaSourceIds:['source'],baseline:{public:{sha256:'a'},internal:{sha256:'b'}},publicManifest:{markets:{china:{count:3}}},internalManifest:{sources:{source:{count:1}}}});assert.equal(r.rows,4);assert.equal(r.uniqueIds,2);assert.equal(r.partitions[0].uniqueIds,2);assert.equal(r.partitions[0].duplicateRows,1);assert.equal(r.serializedRowBytes,3*Buffer.byteLength(JSON.stringify(a))+Buffer.byteLength(JSON.stringify(b)));assert(r.partitions.every(x=>x.declaredCountMatches));assert(!JSON.stringify(r).includes('private-id'));assert(!JSON.stringify(r).includes('DO_NOT_OUTPUT'));assert.throws(()=>c.add({}),/closed/);});
test('caps refuse, not truncate or fabricate complete inventory',()=>{const c=createCaptureInventory({maxRows:1,maxIdBytes:100});assert.throws(()=>c.add({kind:'public',identity:'china',rows:[{id:'a'},{id:'b'}]}),/row_budget/);c.abort();assert.throws(()=>c.finish({}),/closed/);const d=createCaptureInventory({maxIdBytes:1});assert.throws(()=>d.add({kind:'public',identity:'china',rows:[{id:'a'}]}),/id_budget/);});
test('genuine capture owns frozen inventory; forged capability refused',async()=>{const root=await fs.mkdtemp(path.join(os.tmpdir(),'capture-inventory-'));try{const P='catalog/manifest.json',I='catalog/internal/manifest.json',s='autohome_used_china_open',k='catalog/internal/offers/'+s+'/x.json';const data=new Map([[P,{generationId:'gen',markets:{china:{count:1,chunks:['x']}}}],[I,{generationId:'int',sources:{[s]:{count:1,chunks:[k]}}}],['catalog/generations/gen/offers/china/x.json',[{id:'a',market:'china',sourceId:s}]],[k,[{id:'a',market:'china',sourceId:s}]]]);const calls=[],events=[];const cap=await captureCurrentInputs({directory:path.join(root,'capture'),chinaSourceIds:[s],assertAuthority(){},progress(e){events.push(e);},maxDiskBytes:100000,transport:async({key,reserveBytes})=>{calls.push(key);const body=Buffer.from(JSON.stringify(data.get(key)));await reserveBytes(body.length);return{body,bytes:body.length,etag:hash(body),sha256:hash(body)};}});const report=resolveCaptureInventory(cap);assert.equal(calls.length,6);assert.deepEqual(events.filter(e=>e.phaseKey).map(e=>[e.progressCompleted,e.progressTotal,e.progressUnit]),[[2,4,"objects"],[3,4,"objects"],[4,4,"objects"]]);assert.equal(report.rows,2);assert.equal(report.uniqueIds,1);assert.equal(report.uniqueChinaIds,1);assert.equal(report.uniqueProtectedIds,0);assert.deepEqual(report.baseline,cap.baseline);assert(Object.isFrozen(report));assert(Object.isFrozen(report.partitions[0]));assert.throws(()=>resolveCaptureInventory({...cap}),/capability/);}finally{await fs.rm(root,{recursive:true,force:true});}});

test('empty and absent descriptors are explicit, duplicate roles distinct',()=>{const c=createCaptureInventory();c.add({kind:'public',identity:'china',rows:[{id:'a'},{id:'a'}]});c.add({kind:'internal',identity:'used',rows:[{id:'a'}]});const r=c.finish({baseline:{},chinaSourceIds:['used','new'],publicManifest:{markets:{china:{count:2},korea:{count:2,chunks:[]},japan:{count:0,chunks:[]}}},internalManifest:{sources:{used:{count:1}}}});assert.equal(r.totalDuplicateOccurrences,2);assert.equal(r.withinPartitionDuplicateOccurrences,1);assert.equal(r.crossPartitionDuplicateOccurrences,1);assert.equal(r.partitions.find(x=>x.identity==='korea').declaredCountMatches,false);assert.equal(r.partitions.find(x=>x.identity==='japan').declaredCountMatches,true);assert.equal(r.partitions.find(x=>x.identity==='new').descriptorPresent,false);});

test('image aggregate follows native key precedence, per-row dedup and30 cap without retaining keys',()=>{const c=createCaptureInventory();const images=[{checksum:'sum',url:'secret-url'},{id:'sum'},{objectKey:'🙂'},{url:'u'},...Array.from({length:40},(_,i)=>({url:'photo-'+i}))];const row={id:'owner',market:'china',images};c.add({kind:'public',identity:'china',rows:[row,row]});const r=c.finish({baseline:{},chinaSourceIds:[],publicManifest:{markets:{china:{count:2}}},internalManifest:{sources:{}}});const selected=['sum','🙂','u',...Array.from({length:27},(_,i)=>'photo-'+i)];assert.equal(r.imageOccurrences,60);assert.equal(r.imageOwnerUtf8BytesUpper,2*selected.reduce((n,k)=>n+Buffer.byteLength(k)+5+16,0));assert.equal(r.imageOwnerUtf16PayloadBytesUpper,2*selected.reduce((n,k)=>n+Buffer.byteLength(k,'utf16le')+10,0));assert.equal(r.partitions[0].maxImageKeyUtf8Bytes,8);assert(!JSON.stringify(r).includes('secret-url'));assert(!JSON.stringify(r).includes('photo-'));});

import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs/promises';
import{createSourceBatchDriver as actual,resolveSourceBatchDriver as resolveActual}from'./source-batch-driver.mjs';
async function fixture(){let code=await fs.readFile(new URL('./source-batch-driver.mjs',import.meta.url),'utf8');const id='driver_'+Math.random(),s={epochs:1,events:[],fail:false};globalThis[id]=s;code=code.replace(/import \{createSourceReadScope\} from '[^']+';/,`const s=globalThis[${JSON.stringify(id)}];async function createSourceReadScope(){return{async withRead(fn){if(s.fail)throw Error('native_failed');return fn(()=>{if(s.fail)throw Error('native_failed');});},async checkpoint(){if(s.fail)throw Error('native_failed');return{epoch:++s.epochs};},async close(){if(s.fail)throw Error('native_failed');}};}`).replace(/import \{MAX_SOURCE_PHASE_MS\} from '[^']+';/,'const MAX_SOURCE_PHASE_MS=900000;');const mod=await import('data:text/javascript;base64,'+Buffer.from(code).toString('base64'));const options={sourceCapability:{},nativeSession:{},progress:e=>s.events.push(e)};return{s,mod,options,clean:()=>delete globalThis[id]};}
test('real factory and resolver refuse forged capabilities',async()=>{await assert.rejects(actual({sourceCapability:{},progress(){}}),/capability/);assert.throws(()=>resolveActual({}),/capability/);});
