function git(root,args){return execFileSync('git',args,{cwd:root,encoding:'utf8',maxBuffer:32*1024**2}).trim();}
export async function nativeInventory(root,pin){root=await fs.realpath(root);if(git(root,['rev-parse','HEAD'])!==pin)throw Error('package_native_pin');if(git(root,['status','--porcelain','--untracked-files=all','--','apps','packages','scripts','package.json','package-lock.json']))throw Error('package_native_dirty');const tree=git(root,['rev-parse','HEAD^{tree}']);const entries=[];
