// The parser discovers literal operational edges, not computed native authority.
// Dynamic sites must receive independent reviewed digest acceptance before activation.
export async function operationalInventory(root,ts){const queue=['production/runner.mjs'],seen=new Set(),files=[],dynamicSites=[];
 while(queue.length){const rel=safeRelative(queue.pop());if(seen.has(rel))continue;seen.add(rel);const bytes=await body(root,rel),text=bytes.toString('utf8');if(/(?:\/workspace\/|\/home\/agent\/|file:\/\/\/)/.test(text))throw Error('package_absolute_runtime_path');files.push({path:rel,bytes:bytes.length,sha256:hash(bytes)});const ast=ts.createSourceFile(rel,text,ts.ScriptTarget.Latest,true,ts.ScriptKind.JS);
