export async function buildPackage({operationalRoot,publisherRoot,runtimeRoot,outputDirectory,reviewedDynamicSitesSha256=null}){const roots=await Promise.all([operationalRoot,publisherRoot,runtimeRoot].map(x=>fs.realpath(x)));if(new Set(roots).size!==3||roots.some((a,i)=>roots.some((b,j)=>i!==j&&(a.startsWith(b+'/')||b.startsWith(a+'/')))))throw Error('package_foreign_root_layout');[operationalRoot,publisherRoot,runtimeRoot]=roots;if(!path.isAbsolute(outputDirectory))throw Error('package_output_layout');const output=path.resolve(outputDirectory),parent=await fs.realpath(path.dirname(output));if(parent!==path.dirname(output)||roots.some(r=>output===r||output.startsWith(r+'/')||r.startsWith(output+'/')))throw Error('package_output_layout');const ts=createRequire(path.join(publisherRoot,'package.json'))('typescript');const operational=await operationalInventory(operationalRoot,ts);if(reviewedDynamicSitesSha256!==null&&reviewedDynamicSitesSha256!==operational.dynamicSitesSha256)throw Error('package_dynamic_review_changed');const native={publisher:await nativeInventory(publisherRoot,PINS.publisher),runtime:await nativeInventory(runtimeRoot,PINS.runtime)};const toolchain={node:process.version,npm:execFileSync('npm',['--version'],{encoding:'utf8'}).trim(),typescript:ts.version,dependencyInstallation:'required: npm ci from each exact root lock; installed dependency integrity not asserted by this source manifest'};
 const manifest={version:1,layout:{operational:'operational',publisher:'publisher',runtime:'runtime'},operational,native,toolchain,dynamicSitesReviewed:reviewedDynamicSitesSha256!==null,activationReady:false,excluded:['data','raw','fixtures','harness','node_modules'],remainingGates:['independent dynamic-import-site review','separate require/createRequire/source-extraction callable dependency review','exact lock-based dependency installation','source/runtime/knowledge/session authority','resource admission and whole-run acceptance']};
 await fs.mkdir(outputDirectory,{recursive:false,mode:0o700});for(const e of operational.files){const dest=path.join(outputDirectory,'operational',e.path);await fs.mkdir(path.dirname(dest),{recursive:true});const b=await body(operationalRoot,e.path);if(hash(b)!==e.sha256)throw Error('package_source_changed');await fs.writeFile(dest,b,{flag:'wx',mode:0o444});}await verifyFileInventory(operationalRoot,operational.files);await fs.writeFile(path.join(outputDirectory,'SOURCE_MANIFEST.json'),JSON.stringify(manifest),{flag:'wx',mode:0o444});return{manifestSha256:hash(JSON.stringify(manifest)),operationalFiles:operational.files.length,dynamicSites:operational.dynamicSites.length,dynamicSitesSha256:operational.dynamicSitesSha256,activationReady:false};}
export async function verifyPackage({directory,expectedManifestSha256,publisherRoot,runtimeRoot}){if(!/^[a-f0-9]{64}$/.test(expectedManifestSha256||''))throw Error('package_manifest_digest');const manifestPath=path.join(directory,'SOURCE_MANIFEST.json');if((await fs.stat(manifestPath)).size>16*1024**2)throw Error('package_manifest_binding');const b=await body(directory,'SOURCE_MANIFEST.json');if(b.length>16*1024**2||hash(b)!==expectedManifestSha256)throw Error('package_manifest_binding');const m=JSON.parse(b);if(m.version!==1||m.native.publisher.revision!==PINS.publisher||m.native.runtime.revision!==PINS.runtime)throw Error('package_manifest_pin');await verifyFileInventory(path.join(directory,'operational'),m.operational.files);for(const[k,root]of Object.entries({publisher:publisherRoot,runtime:runtimeRoot})){const actual=await nativeInventory(root,PINS[k]);if(JSON.stringify(actual)!==JSON.stringify(m.native[k]))throw Error('package_native_inventory_changed');}if(process.version!==m.toolchain.node||execFileSync('npm',['--version'],{encoding:'utf8'}).trim()!==m.toolchain.npm||createRequire(path.join(publisherRoot,'package.json'))('typescript').version!==m.toolchain.typescript)throw Error('package_toolchain_changed');return{sourceVerified:true,activationReady:false,dynamicSitesReviewed:m.dynamicSitesReviewed};}

