import{createHash,createHmac}from'node:crypto';import{spawn}from'node:child_process';import{writeFile}from'node:fs/promises';import{pathToFileURL}from'node:url';
const ENDPOINT='https://s3.regru.cloud',BUCKET='avtocena-staging-8120751';const sha=s=>createHash('sha256').update(s).digest('hex'),hmac=(k,s)=>createHmac('sha256',k).update(s).digest();
export function signedGet(kind,credentials,date=new Date()){
 if(!['acl','policy'].includes(kind))throw Error('probe_key_denied');
 if(!credentials.accessKeyId||!credentials.secretAccessKey)throw Error('probe_credentials_missing');
 const pathname='/'+BUCKET,query=kind+'=',url=ENDPOINT+pathname+'?'+query;
 const stamp=date.toISOString().replace(/[:-]|\.\d{3}/g,''),day=stamp.slice(0,8),scope=`${day}/us-east-1/s3/aws4_request`;
 const headers={host:'s3.regru.cloud','x-amz-content-sha256':sha(''),'x-amz-date':stamp};
 const names=Object.keys(headers).sort(),canonical=names.map(k=>`${k}:${headers[k]}\n`).join('');
 const request=['GET',pathname,query,canonical,names.join(';'),sha('')].join('\n');
 const signing=hmac(hmac(hmac(hmac('AWS4'+credentials.secretAccessKey,day),'us-east-1'),'s3'),'aws4_request');
 const signature=createHmac('sha256',signing).update(`AWS4-HMAC-SHA256\n${stamp}\n${scope}\n${sha(request)}`).digest('hex');
 headers.authorization=`AWS4-HMAC-SHA256 Credential=${credentials.accessKeyId}/${scope}, SignedHeaders=${names.join(';')}, Signature=${signature}`;
 return {url,options:{method:'GET',headers,redirect:'error'}};
}

export async function read(kind,{credentials,fetchImpl=fetch,timeoutMs=10000}={}){const r=signedGet(kind,credentials),c=new AbortController(),timer=setTimeout(()=>c.abort(),timeoutMs);try{const x=await fetchImpl(r.url,{...r.options,signal:c.signal});if(Number(x.headers.get('content-length')||0)>65536){await x.body?.cancel();return{kind,status:x.status,body:''};}const reader=x.body?.getReader();if(!reader)return{kind,status:x.status,body:''};let size=0;const parts=[];try{for(;;){const r=await reader.read();if(r.done)break;size+=r.value.length;if(size>65536)return{kind,status:x.status,body:''};parts.push(r.value);}}finally{await reader.cancel().catch(()=>{});reader.releaseLock();}return{kind,status:x.status,body:Buffer.concat(parts,size).toString('utf8')};}finally{clearTimeout(timer);c.abort();}}
async function classify(input){return await new Promise((resolve,reject)=>{const child=spawn('python3',[new URL('./classify.py',import.meta.url).pathname],{stdio:['pipe','pipe','ignore']});let n=0;const parts=[];const timer=setTimeout(()=>child.kill('SIGKILL'),5000);child.stdout.on('data',b=>{n+=b.length;if(n>2048)child.kill('SIGKILL');else parts.push(b);});child.on('error',reject);child.on('close',code=>{clearTimeout(timer);try{if(code!==0||n>2048)throw Error();resolve(JSON.parse(Buffer.concat(parts).toString()));}catch{reject(Error('privacy_classifier_unknown'));}});child.stdin.end(JSON.stringify(input));});}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href){const results={};try{const credentials={accessKeyId:process.env.YC_OBJECT_STORAGE_ACCESS_KEY_ID,secretAccessKey:process.env.YC_OBJECT_STORAGE_SECRET_ACCESS_KEY};for(const kind of ['acl','policy']){try{results[kind]=await classify(await read(kind,{credentials}));}catch{results[kind]={classification:'unknown',httpStatus:null};}}results.readOnly=true;results.privacyEstablished=false;await writeFile('checkpoint-privacy.json',JSON.stringify(results));console.log(JSON.stringify(results));if(results.acl?.classification==='unknown'||results.policy?.classification==='unknown')process.exitCode=2;}catch{console.log('{"classification":"unknown","readOnly":true,"privacyEstablished":false}');process.exitCode=2;}}
